function targetLacks(target: CapabilityLackTarget, edition: Edition, os: RuntimeOs): boolean {
  if (target === 'both') return true
  if (target === 'web') return edition === 'web'
  if (edition !== 'desktop') return false
  if (target === 'desktop-macos') return os === 'macos'
  if (target === 'desktop-wayland') return os === 'linux-wayland'
  return os !== 'linux' && os !== 'linux-wayland'
}

/** Computes the capabilities available for `edition` on `os` (ADR 0030). */
export function capabilitiesForEdition(edition: Edition, os: RuntimeOs): EditionCapabilitySet {
  const set = new Set<EditionCapabilityId>()
  for (const row of EDITION_CAPABILITIES) {
    if (!row.lacks.some((target) => targetLacks(target, edition, os))) set.add(row.id)
  }
  return set
}
